import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"天问","description":"","frontmatter":{"title":"天问","date":"2026-11-24T00:00:00.000Z","seq":13,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"礼魂","link":"/blogs/楚辞/礼魂.html"},"next":{"text":"惜诵","link":"/blogs/楚辞/惜诵.html"}},"headers":[],"relativePath":"blogs/楚辞/天问.md","filePath":"blogs/楚辞/天问.md"}'),o={name:"blogs/楚辞/天问.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="天问" tabindex="-1">天问 <a class="header-anchor" href="#天问" aria-label="Permalink to &quot;天问&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　天问</p><div class="poem"><p class="poem-stanza">曰：</p><p class="poem-stanza">遂古之初，谁传道之？</p><p class="poem-stanza">上下未形，何由考之？</p><p class="poem-stanza">冥昭瞢暗，谁能极之？</p><p class="poem-stanza">冯翼惟象，何以识之？</p><p class="poem-stanza">明明暗暗，惟时何为？</p><p class="poem-stanza">阴阳三合，何本何化？</p><p class="poem-stanza">圜则九重，孰营度之？</p><p class="poem-stanza">惟兹何功，孰初作之？</p><p class="poem-stanza">斡维焉系，天极焉加？</p><p class="poem-stanza">八柱何当，东南何亏？</p><p class="poem-stanza">九天之际，安放安属？</p><p class="poem-stanza">隅隈多有，谁知其数？</p><p class="poem-stanza">天何所沓？</p><p class="poem-stanza">十二焉分？</p><p class="poem-stanza">日月安属？</p><p class="poem-stanza">列星安陈？</p><p class="poem-stanza">出自汤谷，次于蒙汜。</p><p class="poem-stanza">自明及晦，所行几里？</p><p class="poem-stanza">夜光何德，死则又育？</p><p class="poem-stanza">厥利维何，而顾菟在腹？</p><p class="poem-stanza">女岐无合，夫焉取九子？</p><p class="poem-stanza">伯强何处？</p><p class="poem-stanza">惠气安在？</p><p class="poem-stanza">何阖而晦？</p><p class="poem-stanza">何开而明？</p><p class="poem-stanza">角宿未旦，曜灵安藏？</p><p class="poem-stanza">不任汩鸿，师何以尚之？</p><p class="poem-stanza">佥曰</p><p class="poem-stanza">“何忧，何不课而行之？”</p><p class="poem-stanza">鸱龟曳衔，鲧何听焉？</p><p class="poem-stanza">顺欲成功，帝何刑焉？</p><p class="poem-stanza">永遏在羽山，夫何三年不施？</p><p class="poem-stanza">伯禹愎鲧，夫何以变化？</p><p class="poem-stanza">纂就前绪，遂成考功。</p><p class="poem-stanza">何续初继业，而厥谋不同？</p><p class="poem-stanza">洪泉极深，何以窴之？</p><p class="poem-stanza">地方九则，何以坟之？</p><p class="poem-stanza">河海应龙？</p><p class="poem-stanza">何尽何历？</p><p class="poem-stanza">鲧何所营？</p><p class="poem-stanza">禹何所成？</p><p class="poem-stanza">康回冯怒，墬何故以东南倾？</p><p class="poem-stanza">九州安错？</p><p class="poem-stanza">川谷何洿？</p><p class="poem-stanza">东流不溢，孰知其故？</p><p class="poem-stanza">东西南北，其修孰多？</p><p class="poem-stanza">南北顺椭，其衍几何？</p><p class="poem-stanza">昆仑悬圃，其尻安在？</p><p class="poem-stanza">增城九重，其高几里？</p><p class="poem-stanza">四方之门，其谁从焉？</p><p class="poem-stanza">西北辟启，何气通焉？</p><p class="poem-stanza">日安不到？</p><p class="poem-stanza">烛龙何照？</p><p class="poem-stanza">羲和之未扬，若华何光？</p><p class="poem-stanza">何所冬暖？</p><p class="poem-stanza">何所夏寒？</p><p class="poem-stanza">焉有石林？</p><p class="poem-stanza">何兽能言？</p><p class="poem-stanza">焉有虬龙，负熊以游？</p><p class="poem-stanza">雄虺九首，鯈忽焉在？</p><p class="poem-stanza">何所不死？</p><p class="poem-stanza">长人何守？</p><p class="poem-stanza">靡蓱九衢，枲华安居？</p><p class="poem-stanza">灵蛇吞象，厥大何如？</p><p class="poem-stanza">黑水玄趾，三危安在？</p><p class="poem-stanza">延年不死，寿何所止？</p><p class="poem-stanza">鲮鱼何所？</p><p class="poem-stanza">鬿堆焉处？</p><p class="poem-stanza">羿焉彃日？</p><p class="poem-stanza">乌焉解羽？</p><p class="poem-stanza">禹之力献功，降省下土四方。</p><p class="poem-stanza">焉得彼嵞山女，而通之於台桑？</p><p class="poem-stanza">闵妃匹合，厥身是继。</p><p class="poem-stanza">胡维嗜不同味，而快鼌饱？</p><p class="poem-stanza">启代益作后，卒然离蠥。</p><p class="poem-stanza">何启惟忧，而能拘是达？</p><p class="poem-stanza">皆归射鞫，而无害厥躬。</p><p class="poem-stanza">何后益作革，而禹播降？</p><p class="poem-stanza">启棘宾商，《九辨》《九歌》。</p><p class="poem-stanza">何勤子屠母，而死分竟地？</p><p class="poem-stanza">帝降夷羿，革孽夏民。</p><p class="poem-stanza">胡射夫河伯，而妻彼雒嫔？</p><p class="poem-stanza">冯珧利决，封豨是射。</p><p class="poem-stanza">何献蒸肉之膏，而后帝不若？</p><p class="poem-stanza">浞娶纯狐，眩妻爰谋。</p><p class="poem-stanza">何羿之射革，而交吞揆之？</p><p class="poem-stanza">阻穷西征，岩何越焉？</p><p class="poem-stanza">化而为黄熊，巫何活焉？</p><p class="poem-stanza">咸播秬黍，莆雚是营。</p><p class="poem-stanza">何由并投，而鲧疾修盈？</p><p class="poem-stanza">白蜺婴茀，胡为此堂？</p><p class="poem-stanza">安得夫良药，不能固臧？</p><p class="poem-stanza">天式从横，阳离爰死。</p><p class="poem-stanza">大鸟何鸣，夫焉丧厥体？</p><p class="poem-stanza">蓱号起雨，何以兴之？</p><p class="poem-stanza">撰体协胁，鹿何膺之？</p><p class="poem-stanza">鳌戴山抃，何以安之？</p><p class="poem-stanza">释舟陵行，何之迁之？</p><p class="poem-stanza">惟浇在户，何求于嫂？</p><p class="poem-stanza">何少康逐犬，而颠陨厥首？</p><p class="poem-stanza">女歧缝裳，而馆同爰止。</p><p class="poem-stanza">何颠易厥首，而亲以逢殆？</p><p class="poem-stanza">汤谋易旅，何以厚之？</p><p class="poem-stanza">覆舟斟寻，何道取之？</p><p class="poem-stanza">桀伐蒙山，何所得焉？</p><p class="poem-stanza">妺嬉何肆，汤何殛焉？</p><p class="poem-stanza">舜闵在家，父何以鳏？</p><p class="poem-stanza">尧不姚告，二女何亲？</p><p class="poem-stanza">厥萌在初，何所亿焉？</p><p class="poem-stanza">璜台十成，谁所极焉？</p><p class="poem-stanza">登立为帝，孰道尚之？</p><p class="poem-stanza">女娲有体，孰制匠之？</p><p class="poem-stanza">舜服厥弟，终然为害。</p><p class="poem-stanza">何肆犬豕，而厥身不危败？</p><p class="poem-stanza">吴获迄古，南岳是止。</p><p class="poem-stanza">孰期去斯，得两男子？</p><p class="poem-stanza">缘鹄饰玉，后帝是飨。</p><p class="poem-stanza">何承谋夏桀，终以灭丧？</p><p class="poem-stanza">帝乃降观，下逢伊挚。</p><p class="poem-stanza">何条放致罚，而黎服大说？</p><p class="poem-stanza">简狄在台，喾何宜？</p><p class="poem-stanza">玄鸟致贻，女何喜？</p><p class="poem-stanza">该秉季德，厥父是臧。</p><p class="poem-stanza">胡终弊于有扈，牧夫牛羊？</p><p class="poem-stanza">干协时舞，何以怀之？</p><p class="poem-stanza">平胁曼肤，何以肥之？</p><p class="poem-stanza">有扈牧竖，云何而逢？</p><p class="poem-stanza">击床先出，其命何从？</p><p class="poem-stanza">恒秉季德，焉得夫朴牛？</p><p class="poem-stanza">何往营班禄，不但还来？</p><p class="poem-stanza">昏微循迹，有狄不宁。</p><p class="poem-stanza">何繁鸟萃棘，负子肆情？</p><p class="poem-stanza">眩弟并淫，危害厥兄。</p><p class="poem-stanza">何变化以作诈，而后嗣逢长？</p><p class="poem-stanza">成汤东巡，有莘爰极。</p><p class="poem-stanza">何乞彼小臣，而吉妃是得？</p><p class="poem-stanza">水滨之木，得彼小子。</p><p class="poem-stanza">夫何恶之，媵有莘之妇？</p><p class="poem-stanza">汤出重泉，夫何辠尤？</p><p class="poem-stanza">不胜心伐帝，夫谁使挑之？</p><p class="poem-stanza">会朝争盟，何践吾期？</p><p class="poem-stanza">苍鸟群飞，孰使萃之？</p><p class="poem-stanza">列击纣躬，叔旦不嘉。</p><p class="poem-stanza">何亲揆发足，周之命以咨嗟？</p><p class="poem-stanza">授殷天下，其位安施？</p><p class="poem-stanza">反成乃亡，其罪伊何？</p><p class="poem-stanza">争遣伐器，何以行之？</p><p class="poem-stanza">并驱击翼，何以将之？</p><p class="poem-stanza">昭后成游，南土爰底。</p><p class="poem-stanza">厥利惟何，逢彼白雉？</p><p class="poem-stanza">穆王巧梅，夫何为周流？</p><p class="poem-stanza">环理天下，夫何索求？</p><p class="poem-stanza">妖夫曳炫，何号于市？</p><p class="poem-stanza">周幽谁诛？</p><p class="poem-stanza">焉得夫褒姒？</p><p class="poem-stanza">天命反侧，何罚何佑？</p><p class="poem-stanza">齐桓九会，卒然身杀。</p><p class="poem-stanza">彼王纣之躬，孰使乱惑？</p><p class="poem-stanza">何恶辅弼，谗谄是服？</p><p class="poem-stanza">比干何逆，而抑沈之？</p><p class="poem-stanza">雷开阿顺，而赐封之？</p><p class="poem-stanza">何圣人之一德，卒其异方？</p><p class="poem-stanza">梅伯受醢，箕子详狂？</p><p class="poem-stanza">稷维元子，帝何竺之？</p><p class="poem-stanza">投之于冰上，鸟何燠之？</p><p class="poem-stanza">何冯弓挟矢，殊能将之？</p><p class="poem-stanza">既惊帝切激，何逢长之？</p><p class="poem-stanza">伯昌号衰，秉鞭作牧。</p><p class="poem-stanza">何令彻彼岐社，命有殷国？</p><p class="poem-stanza">迁藏就岐，何能依？</p><p class="poem-stanza">殷有惑妇，何所讥？</p><p class="poem-stanza">受赐兹醢，西伯上告。</p><p class="poem-stanza">何亲就上帝罚，殷之命以不救？</p><p class="poem-stanza">师望在肆，昌何识？</p><p class="poem-stanza">鼓刀扬声，后何喜？</p><p class="poem-stanza">武发杀殷，何所悒？</p><p class="poem-stanza">载尸集战，何所急？</p><p class="poem-stanza">伯林雉经，维其何故？</p><p class="poem-stanza">何感天抑墬，夫谁畏惧？</p><p class="poem-stanza">皇天集命，惟何戒之？</p><p class="poem-stanza">受礼天下，又使至代之？</p><p class="poem-stanza">初汤臣挚，后兹承辅。</p><p class="poem-stanza">何卒官汤，尊食宗绪？</p><p class="poem-stanza">勋阖梦生，少离散亡。</p><p class="poem-stanza">何壮武历，能流厥严？</p><p class="poem-stanza">彭铿斟雉，帝何飨？</p><p class="poem-stanza">受寿永多，夫何久长？</p><p class="poem-stanza">中央共牧，后何怒？</p><p class="poem-stanza">蜂蛾微命，力何固？</p><p class="poem-stanza">惊女采薇，鹿何佑？</p><p class="poem-stanza">北至回水，萃何喜？</p><p class="poem-stanza">兄有噬犬，弟何欲？</p><p class="poem-stanza">易之以百两，卒无禄？</p><p class="poem-stanza">薄暮雷电，归何忧？</p><p class="poem-stanza">厥严不奉，帝何求？</p><p class="poem-stanza">伏匿穴处，爰何云？</p><p class="poem-stanza">荆勋作师，夫何长？</p><p class="poem-stanza">悟过改更，我又何言？</p><p class="poem-stanza">吴光争国，久余是胜。</p><p class="poem-stanza">何环穿自闾社丘陵，爰出子文？</p><p class="poem-stanza">吾告堵敖以不长。</p><p class="poem-stanza">何试上自予，忠名弥彰？</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
